    ageText(item) { return (item.count===1 ? 'Lleva ' : 'El pendiente más antiguo lleva ')+item.oldestAgeDays+(item.oldestAgeDays===1?' día.':' días.'); },
    reason(id, count) { const one=count===1; return {
